import {seed,dispatch,markets,vendor,product,available,issues,gates,routePreview,statementRows,totals,scanSlas} from './domain.js';
const KEY='ati-concessions-v5';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==5)state=seed();}catch{state=seed();}
let page=new URLSearchParams(location.search).get('page')||'Overview',selectedVendor=new URLSearchParams(location.search).get('vendor')||sessionStorage.getItem('ecp-vendor')||'V1';
if(!state.vendors.some(v=>v.id===selectedVendor))selectedVendor='V1';
const app=document.body.dataset.app,operator=app==='ati';
let role=sessionStorage.getItem('ecp-role')||'Admin',language=localStorage.getItem('ecp-language')||'en',filterMarket='All',query='',statusFilter='All',modalSubmit=null,reportFrom='2026-09-01',reportTo='2026-09-30';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const actor=()=>({role:operator?role:'Vendor',name:operator?(role==='Finance'?'ATI Finance':'Aline Kharouf'):vendor(state,selectedVendor).contact,vendorId:operator?undefined:selectedVendor});
const t=(en,ar)=>language==='ar'?(ar||en):en;
const money=(n,c='AED')=>`${c} ${Number(n||0).toLocaleString('en-GB',{minimumFractionDigits:markets.Kuwait.currency===c?3:2,maximumFractionDigits:3})}`;
