const button=(label,a,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${a}" data-id="${e(id)}">${e(label)}</button>`;
const primary=(label,a,id='')=>button(label,a,id,operator?'violet':'dark');
const link=(label,p)=>`<a class="btn" href="${operator?'/ati/':'/partner/'}?page=${encodeURIComponent(p)}&vendor=${selectedVendor}">${e(label)}</a>`;
const section=(title,body,action='')=>`<section class="card"><div class="section-title"><h2>${e(title)}</h2>${action}</div>${body}</section>`;
const empty=(text)=>`<div class="empty-state"><span>◇</span><h3>${e(text)}</h3><p>${t('Use the actions above to continue this workflow.','استخدم الإجراءات أعلاه لمتابعة العمل.')}</p></div>`;
const table=(heads,rows)=>`<div class="table-card"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">${empty(t('No records in this view','لا توجد سجلات'))}</td></tr>`}</tbody></table></div>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){localStorage.setItem(KEY,JSON.stringify(state));}
function commit(type,p,renderNow=true){const next=structuredClone(state);const result=dispatch(next,type,p,actor());scanSlas(next);const old=state;state=next;try{persist();}catch{state=old;throw Error('Browser storage is full. Use smaller images/documents or export a backup.');}if(renderNow)render();return result;}
function safe(fn){try{return fn();}catch(err){toast(err.message);const box=$('#form-error');if(box)box.textContent=err.message;return false;}}
function scopedVendor(v){return v.business===state.business&&(filterMarket==='All'||v.market===filterMarket)&&(operator||v.id===selectedVendor);}
function scopedProducts(){return state.products.filter(p=>scopedVendor(vendor(state,p.vendorId)));}
function match(record,status){return (!query||JSON.stringify(record).toLowerCase().includes(query.toLowerCase()))&&(statusFilter==='All'||status===statusFilter);}
function field(name,label,value='',type='text',options=null){return `<label class="field">${e(label)}${options?`<select name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(l)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea name="${name}">${e(value)}</textarea>`:type==='checkbox'?`<input type="checkbox" name="${name}" ${value?'checked':''}>`:`<input name="${name}" type="${type}" value="${e(value)}" ${type==='number'?'step="any"':''}>`}</label>`;}
function closeModal(){const r=$('#modal-root');if(r)r.innerHTML='';modalSubmit=null;}
function modal(title,body,submit=null,label='Save changes'){let r=$('#modal-root');if(!r){r=document.createElement('div');r.id='modal-root';document.body.append(r);}r.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><button class="close-x" data-action="close" aria-label="Close dialog">×</button><span class="eyebrow">${operator?'ATI OPERATIONS':'PARTNER WORKSPACE'}</span><h2>${e(title)}</h2>${submit?'<form id="dialog-form">':''}${body}<p id="form-error" class="form-error" role="alert"></p>${submit?`<div class="modal-actions"><button type="button" class="btn" data-action="close">${t('Cancel','إلغاء')}</button><button class="btn ${operator?'violet':'dark'}" type="submit">${e(label)}</button></div></form>`:''}</section></div>`;modalSubmit=submit;requestAnimationFrame(()=>r.querySelector('input,select,button')?.focus());}
function form(title,fields,fn,label){modal(title,`<div class="field-grid">${fields}</div>`,fn,label);}
function confirmReason(title,fn){form(title,field('reason',t('Reason','السبب'),'','textarea'),fd=>{fn(fd.get('reason'));},t('Confirm','تأكيد'));}
function csvDownload(name,rows){const csv=rows.map(r=>r.map(v=>{let x=String(v??'');if(/^[=+@]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"';}).join(',')).join('\r\n');download(name,'\ufeff'+csv,'text/csv;charset=utf-8');}
function download(name,data,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function recordHistory(id){const rows=state.audit.filter(x=>String(x.entity)===id||x.changes.some(c=>c.id===id));return rows.length?rows.map(x=>`<div class="timeline-row"><b>${e(x.type)} · ${e(x.actor)}</b><small>${date(x.at)} ${e(x.reason)}</small></div>`).join(''):'No changes recorded yet.';}
function toolbar(){return `<div class="workspace-controls"><span class="sim-label"><i></i>${t('Interactive demo · simulated integrations','عرض تفاعلي · تكاملات محاكاة')}</span><div>${operator?`<label>Business <select id="business-context">${state.businesses.map(b=>`<option ${b===state.business?'selected':''}>${e(b)}</option>`).join('')}</select></label><label>Market <select id="market-context">${['All',...Object.keys(markets)].map(m=>`<option ${m===filterMarket?'selected':''}>${m}</option>`).join('')}</select></label><label>Role <select id="role-context">${['Admin','Operator','Finance','Viewer'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select></label>`:`<label>${t('Demo brand','العلامة')} <select id="vendor-context">${state.vendors.map(v=>`<option value="${v.id}" ${v.id===selectedVendor?'selected':''}>${e(v.name)}</option>`).join('')}</select></label>`}<button class="btn small" data-action="language">${language==='ar'?'English':'العربية'}</button><a class="btn small" href="/index.html">${t('Demo home','الرئيسية')}</a></div></div>`;}
function heading(title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${operator?e(state.business)+' · EXTERNAL CONCESSIONS':e(vendor(state,selectedVendor).name)}</span><h1>${e(title)}</h1><p>${e(desc)}</p></div><div class="page-actions">${actions}</div></div>`;}
function filterBar(statuses=[]){return `<div class="filters"><input id="record-search" value="${e(query)}" placeholder="${t('Search records…','البحث في السجلات…')}" aria-label="Search records"><select id="status-filter" aria-label="Filter status">${['All',...new Set(statuses)].map(x=>`<option ${x===statusFilter?'selected':''}>${e(x)}</option>`).join('')}</select>${button(t('Export view','تصدير'),'exportView')}</div>`;}
function cards(items){return `<div class="grid-4">${items.map(([label,value,note])=>`<div class="metric"><label>${e(label)}</label><strong>${e(value)}</strong><small>${e(note||'')}</small></div>`).join('')}</div>`;}
const navigation=operator?['Overview','Applications','Vendors & brands','Catalogue','Inventory','Orders','Returns & exchanges','Commercials','Settlements','Rules & access','Integrations','Appointments','Exceptions','Reporting','Audit log','Demo guide']:['Overview','Profile & documents','Catalogue','Inventory','Orders','Returns & exchanges','Settlements','Notifications','Demo guide'];
