function reportDateRow(){return `<div class="filters"><label>Report from <input type="date" id="report-from" value="${reportFrom}"></label><label>Through <input type="date" id="report-to" value="${reportTo}"></label>${button('Download shareable report','reportShare')}</div>`;}
