function productModal(id){const p=id?product(state,id):{vendorId:operator?state.vendors.find(scopedVendor)?.id:selectedVendor,sku:'',name:'',ar:'',parent:'',category:'Dresses',color:'Black',size:'M',price:850,floor:operator?600:0,discount:0,promoFunding:0,asset:'',assetValid:false};if(!p.vendorId)throw Error('Invite a vendor in this business first');form(id?'Product detail · '+p.sku:'Create product',field('vendorId','Vendor',p.vendorId,'text',state.vendors.filter(scopedVendor).map(v=>[v.id,v.name]))+field('sku','SKU',p.sku)+field('name','English title',p.name)+field('ar','Arabic title',p.ar)+field('parent','Parent style ID',p.parent)+field('category','ATI category',p.category,'text',['Dresses','Tops','Skirts','Bags','Jackets','Accessories','Beauty','Home'])+field('color','Colour',p.color)+field('size','Size',p.size)+field('price','Price',p.price,'number')+field('floor','Price floor',p.floor,'number')+field('discount','Discount %',p.discount,'number')+field('promoFunding','Brand promotion funding %',p.promoFunding,'number')+field('asset','Image URL / DAM reference / asset name',p.asset)+field('assetValid','Image reviewed: 800px minimum, acceptable quality',p.assetValid,'checkbox')+(operator?field('overrideReason','Operator price-floor override reason',p.overrideReason||''):''),fd=>{const fields=Object.fromEntries(fd);for(const k of ['price','floor','discount','promoFunding'])fields[k]=Number(fields[k]);fields.assetValid=fd.has('assetValid');delete fields.vendorId;if(id&&fd.get('vendorId')!==p.vendorId)throw Error('Vendor ownership cannot be changed');const newId=commit('product',{id,vendorId:fd.get('vendorId'),fields});closeModal();productModal(newId);return false;},'Save draft');const f=$('#dialog-form');f.insertAdjacentHTML('afterbegin',id?`<div class="notice">${issues(state,p).length?issues(state,p).map(e).join(' · '):'Content checks passed'}${p.feedback?'<br>'+e(p.feedback):''}</div>`:'');if(id)f.insertAdjacentHTML('beforeend',`<div class="action-row product-actions">${button('Translation preview','translate',id)}${button('Upload image / ZIP','assets',id)}${button('Image generation brief','imageBrief',id)}${button('Duplicate comparison','duplicate',id)}${button('Submit for review','submitProduct',id)}${operator?button('Approve','approveProduct',id)+button('Request corrections','rejectProduct',id)+button('Publish ERP → SFCC','publish',id)+button(p.paused?'Resume SKU':'Pause SKU','pauseProduct',id):''}</div><p class="muted">Workflow actions use the saved draft. Save changes first.</p>`);}
