function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quote)throw Error('Unclosed quoted CSV value');return rows;}
async function readSheet(file){if(/\.csv$/i.test(file.name))return parseCSV(await file.text());if(!/\.xlsx$/i.test(file.name))throw Error('Choose CSV or XLSX');const zip=await JSZip.loadAsync(file),xml=new DOMParser(),texts=zip.file('xl/sharedStrings.xml')?xml.parseFromString(await zip.file('xl/sharedStrings.xml').async('string'),'text/xml'):null,ss=texts?[...texts.getElementsByTagName('si')].map(n=>n.textContent):[],sheet=zip.file('xl/worksheets/sheet1.xml');if(!sheet)throw Error('First worksheet not found');const doc=xml.parseFromString(await sheet.async('string'),'text/xml');return [...doc.getElementsByTagName('row')].map(r=>{const a=[];for(const c of r.getElementsByTagName('c')){const ref=c.getAttribute('r').match(/[A-Z]+/)[0];let n=0;for(const l of ref)n=n*26+l.charCodeAt(0)-64;const value=c.getElementsByTagName('v')[0]?.textContent||c.getElementsByTagName('is')[0]?.textContent||'';a[n-1]=c.getAttribute('t')==='s'?ss[Number(value)]:value;}return a;});}
