function saveApplication(){const formEl=$('#application-form');if(!formEl)return;const fd=new FormData(formEl),v=vendor(state,selectedVendor),fields={};for(const k of ['legal','contact','email','licence','address','name','market','method','model'])if(fd.has(k))fields[k]=fd.get(k);if(v.step===1)fields.rights=fd.has('rights');if(v.step===7)fields.consent=fd.has('consent');commit('profile',{vendorId:selectedVendor,fields},false);}
const dataURL=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('File could not be read'));r.readAsDataURL(file);});
const loadImage=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Image could not be decoded'));i.src=src;});
document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-action]');if(target){ev.preventDefault();try{await handle(target.dataset.action,target.dataset.id||'');}catch(err){safe(()=>{throw err;});}return;}const rail=ev.target.closest('[data-ati-nav]');if(rail){ev.preventDefault();const map={'Orders & SLA':'Orders','Catalogue & PIM':'Catalogue','Rules & Automations':'Rules & access','Rules & policies':'Rules & access','Vendor Network':'Vendors & brands'};navigate(map[rail.dataset.atiNav]||rail.dataset.atiNav);}if(ev.target.closest('[data-toast],.bloom-tools button,.bloom-search,.fynd-spark'))toast('This retail / assistant control is outside the concession demo. Use the workspace navigation.');});
document.addEventListener('submit',async ev=>{if(!['dialog-form','application-form'].includes(ev.target.id))return;ev.preventDefault();try{if(ev.target.id==='application-form'){saveApplication();const v=vendor(state,selectedVendor);if(v.step===7){commit('submit',{vendorId:selectedVendor});modal('Application submitted','<p>Your details have been saved. ATI can now review the application in its separate operator console.</p><a class="btn dark" href="/partner/">Continue to partner workspace</a>');}else commit('profile',{vendorId:selectedVendor,fields:{step:v.step+1}});}else{const fn=modalSubmit;if(fn){const result=await fn(new FormData(ev.target));if(result!==false)closeModal();}}}catch(err){safe(()=>{throw err;});}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.dataset.document){const file=el.files[0];if(!file)return;if(file.size>300000)throw Error('Use a sample document smaller than 300 KB');commit('document',{vendorId:selectedVendor,docId:el.dataset.document,file:file.name,content:await dataURL(file)});toast('Document saved with a new version');}if(el.id==='business-context'){state.business=el.value;persist();render();}if(el.id==='market-context'){filterMarket=el.value;render();}if(el.id==='role-context'){role=el.value;sessionStorage.setItem('ecp-role',role);render();}if(el.id==='vendor-context'){selectedVendor=el.value;sessionStorage.setItem('ecp-vendor',selectedVendor);state.business=vendor(state,selectedVendor).business;render();}if(el.id==='report-from'){reportFrom=el.value;render();}if(el.id==='report-to'){reportTo=el.value;render();}if(el.id==='status-filter'){statusFilter=el.value;render();}if(el.closest('#application-form')&&!el.dataset.document)saveApplication();}catch(err){safe(()=>{throw err;});}});
document.addEventListener('input',ev=>{if(ev.target.id==='record-search'){const pos=ev.target.selectionStart;query=ev.target.value;render();const input=$('#record-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if(ev.key==='Tab'&&$('#modal-root .modal')){const els=[...$('#modal-root .modal').querySelectorAll('a,button,input,select,textarea')].filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
